package android.app;import android.content.*;import java.util.*;public class AlertDialog implements DialogInterface {public static List<AlertDialog> shown=new ArrayList<>();public boolean dismissed;public DialogInterface.OnClickListener item,single,positive,negative,neutral;public DialogInterface.OnMultiChoiceClickListener multi;public void dismiss(){dismissed=true;}public static class Builder {AlertDialog d=new AlertDialog(); public Builder(Context c){} public Builder setTitle(String s){return this;}public Builder setTitle(int i){return this;}public Builder setItems(String[] v,DialogInterface.OnClickListener c){d.item=c;return this;}public Builder setSingleChoiceItems(String[]v,int selected,DialogInterface.OnClickListener c){d.single=c;return this;}public Builder setMultiChoiceItems(String[]v,boolean[]selected,DialogInterface.OnMultiChoiceClickListener c){d.multi=c;return this;}public Builder setPositiveButton(int i,DialogInterface.OnClickListener c){d.positive=c;return this;}public Builder setNegativeButton(int i,DialogInterface.OnClickListener c){d.negative=c;return this;}public Builder setNeutralButton(int i,DialogInterface.OnClickListener c){d.neutral=c;return this;}public AlertDialog show(){shown.add(d);return d;}} }
